const fs = require('node:fs');
const root = fs.readFileSync('app/_layout.tsx', 'utf8');
const upstreamPath = require.resolve('@expo/metro-config/babel-transformer');
const transformerPath = require.resolve('@rork-ai/toolkit-sdk/metro-transformer');
require.cache[upstreamPath] = {
  id: upstreamPath,
  filename: upstreamPath,
  loaded: true,
  exports: { transform: ({ src }) => src },
  children: [],
  paths: [],
};
delete require.cache[transformerPath];
Promise.resolve(require(transformerPath).transform({
  filename: `${process.cwd()}/app/_layout.tsx`,
  src: root,
  options: { dev: true },
})).then((output) => {
  if (output.includes('@rork-ai/toolkit-sdk') || output.includes('@ai-sdk/react')) {
    throw new Error('Managed transformer injected the AI SDK dependency graph');
  }
  console.log('Managed-transformer reset simulation: PASS (no provider injection)');
});
NODE

